﻿@page "/"
@inject NavigationManager Navigation

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="text-center my-5">
    <h1>📦 ShipmentTracker</h1>
    <p class="lead">Track your shipments in real-time</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Track a Shipment</h5>
                <div class="input-group">
                    <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-ABC12345)"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                        Track
                    </button>
                </div>
            </div>
        </div>
    </div>
</div>

<AuthorizeView>
    <Authorized>
        <div class="row justify-content-center mt-4">
            <div class="col-md-6">
                <div class="d-flex gap-2 justify-content-center">
                    <a href="my-shipments" class="btn btn-outline-primary">My Shipments</a>
                    <a href="dispatcher" class="btn btn-outline-secondary">Dispatcher Dashboard</a>
                </div>
            </div>
        </div>
    </Authorized>
</AuthorizeView>

@code {
    private string trackingNumber = string.Empty;

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            Navigation.NavigateTo($"track/{trackingNumber.Trim()}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            TrackShipment();
        }
    }
}

