@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

<div class="d-flex justify-content-between align-items-center mb-3">
    <div>
        <label class="me-2">Filter by status:</label>
        <select class="form-select d-inline-block w-auto" @bind="statusFilter">
            <option value="">All</option>
            <option value="Pending">Pending</option>
            <option value="PickedUp">Picked Up</option>
            <option value="InTransit">In Transit</option>
            <option value="OutForDelivery">Out For Delivery</option>
            <option value="Delivered">Delivered</option>
            <option value="Cancelled">Cancelled</option>
        </select>
    </div>
    <a href="dispatcher/create" class="btn btn-success">+ New Shipment</a>
</div>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (FilteredShipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Recipient</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Created</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><a href="track/@shipment.TrackingNumber">@shipment.TrackingNumber</a></td>
                        <td>@shipment.RecipientName</td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>
                            <select class="form-select form-select-sm" value="@shipment.Status"
                                    @onchange="(e) => UpdateStatus(shipment.Id, e.Value?.ToString() ?? shipment.Status)">
                                <option value="Pending">Pending</option>
                                <option value="PickedUp">Picked Up</option>
                                <option value="InTransit">In Transit</option>
                                <option value="OutForDelivery">Out For Delivery</option>
                                <option value="Delivered">Delivered</option>
                                <option value="Cancelled">Cancelled</option>
                            </select>
                        </td>
                        <td>@shipment.CreatedAt.ToString("MMM dd")</td>
                        <td>
                            <a href="track/@shipment.TrackingNumber" class="btn btn-sm btn-outline-primary">View</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string statusFilter = string.Empty;

    private List<ShipmentDto> FilteredShipments => string.IsNullOrEmpty(statusFilter)
        ? shipments
        : shipments.Where(s => s.Status == statusFilter).ToList();

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private async Task UpdateStatus(int id, string newStatus)
    {
        await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
        var shipment = shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
        {
            shipment.Status = newStatus;
        }
    }
}

